{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 동물미용실에 대한 시·구청의 출입·검사 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제23조제1항은 시장 또는 구청장이 법 제86조에 따라 동물의 소유자등 및 각 호의 영업자 등에게 필요한 보고·자료를 제출하게 하거나 해당 시설에 출입하여 운영실태 조사 또는 관계서류를 검사하게 할 수 있다고 정하고 있다. 같은 항 제7호에서 동물미용업을 그 영업자 등의 하나로 명시하고 있으므로, 동물미용실도 출입·검사 대상에 포함된다. 따라서 시나 구청이 동물미용실에 출입하여 검사할 수 있다.",
          "b_ids": "동물보호:제23조제1항, 동물보호:제23조제1항제7호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
